// Questões extras SESI-RS - bloco 1
math.push(...[["Porcentagem","Um tênis custa R$ 240 e entrou em promoção com 15% de desconto. Qual é o preço final?",["R$ 196","R$ 204","R$ 210","R$ 216"],1,"15% de 240 = 36. Então, 240 − 36 = R$ 204."],["Porcentagem","Uma mensalidade de R$ 500 aumentou 8%. Qual passou a ser o valor?",["R$ 520","R$ 530","R$ 540","R$ 550"],2,"8% de 500 = 40. Novo valor: 500 + 40 = R$ 540."],["Porcentagem","Em uma prova de 40 questões, Júlia acertou 30. Qual foi seu percentual de acertos?",["65%","70%","75%","80%"],2,"30 ÷ 40 = 0,75. Logo, 75%."],["Porcentagem","Uma loja vendeu 120 camisetas e 25% eram pretas. Quantas camisetas pretas foram vendidas?",["20","25","30","35"],2,"25% de 120 é a quarta parte de 120: 30."],["Porcentagem","Um produto de R$ 360 teve desconto de 10% e depois mais R$ 20 de abatimento. Qual o preço final?",["R$ 304","R$ 314","R$ 324","R$ 334"],0,"10% de 360 = 36. 360 − 36 − 20 = R$ 304."],["Porcentagem","Uma população de 2.000 pessoas cresceu 5%. Quantas pessoas há agora?",["2.050","2.080","2.100","2.150"],2,"5% de 2.000 = 100. Total: 2.100."],["Porcentagem","Um reservatório de 800 L está com 35% de sua capacidade. Quantos litros contém?",["240 L","260 L","280 L","300 L"],2,"35% de 800 = 0,35 × 800 = 280 L."],["Porcentagem","Um preço passou de R$ 80 para R$ 100. Qual foi o percentual de aumento?",["20%","25%","30%","35%"],1,"O aumento foi de 20. Como 20 ÷ 80 = 0,25, o aumento foi de 25%."],["Frações","Uma pizza foi dividida em 8 partes iguais. Foram comidas 3 partes. Que fração restou?",["3/8","4/8","5/8","6/8"],2,"Restaram 8 − 3 = 5 partes de 8, ou 5/8."],["Frações","De 24 alunos, 3/8 faltaram. Quantos faltaram?",["6","8","9","12"],2,"24 ÷ 8 = 3; 3 × 3 = 9 alunos."],["Frações","Qual fração é equivalente a 6/9 na forma simplificada?",["1/2","2/3","3/4","4/5"],1,"Dividindo numerador e denominador por 3: 6/9 = 2/3."],["Frações","Ana leu 2/5 de um livro na segunda e 1/5 na terça. Que fração leu ao todo?",["2/10","3/5","3/10","4/5"],1,"Com denominadores iguais, some os numeradores: 2/5 + 1/5 = 3/5."],["Frações","Um tanque estava com 7/10 da capacidade e foram usados 2/10. Quanto restou?",["1/2","3/10","5/10","9/10"],2,"7/10 − 2/10 = 5/10, que também equivale a 1/2."],["Frações","Qual é o maior número?",["2/3","3/5","5/8","7/12"],0,"2/3 ≈ 0,667; 3/5 = 0,6; 5/8 = 0,625; 7/12 ≈ 0,583."],["Frações","Uma receita usa 3/4 de xícara de leite. Para fazer meia receita, quanto leite será usado?",["3/8 de xícara","1/2 de xícara","2/3 de xícara","3/4 de xícara"],0,"Metade de 3/4 é 3/8."],["Frações","Em uma corrida, Pedro percorreu 5/6 do trajeto. Que fração ainda falta?",["1/6","1/5","2/6","5/12"],0,"O todo é 6/6. Então, 6/6 − 5/6 = 1/6."],["Números decimais","Uma compra custa R$ 18,90 e outra R$ 7,35. Qual é o total?",["R$ 25,15","R$ 26,25","R$ 26,35","R$ 27,25"],1,"18,90 + 7,35 = 26,25."],["Números decimais","Um rolo tinha 12,5 m de cabo e foram usados 4,75 m. Quanto restou?",["7,25 m","7,50 m","7,75 m","8,25 m"],2,"12,50 − 4,75 = 7,75 m."],["Números decimais","Qual número é maior?",["3,08","3,8","3,18","3,008"],1,"3,8 = 3,80, maior que 3,18, 3,08 e 3,008."],["Números decimais","Um litro de combustível custa R$ 6,20. Quanto custam 5 litros?",["R$ 28,00","R$ 30,00","R$ 31,00","R$ 32,00"],2,"6,20 × 5 = 31,00."],["Números decimais","Uma fita de 9,6 m foi cortada em 4 partes iguais. Quanto mede cada parte?",["2,2 m","2,4 m","2,6 m","2,8 m"],1,"9,6 ÷ 4 = 2,4 m."],["Números decimais","Qual é o resultado de 2,75 + 0,8?",["3,45","3,55","3,65","3,75"],1,"0,8 = 0,80. Então, 2,75 + 0,80 = 3,55."],["Números decimais","Um atleta baixou seu tempo de 12,4 s para 11,85 s. Quanto melhorou?",["0,45 s","0,55 s","0,65 s","0,75 s"],1,"12,40 − 11,85 = 0,55 s."],["Números decimais","Uma garrafa contém 1,5 L. Quantos litros há em 6 garrafas?",["7,5 L","8 L","9 L","9,5 L"],2,"1,5 × 6 = 9 litros."],["Razão e proporção","Em uma mistura, a razão entre suco e água é 2:3. Se há 6 copos de água, quantos copos de suco são usados?",["2","3","4","6"],2,"Se 3 partes correspondem a 6 copos, cada parte vale 2. Suco: 2 × 2 = 4."],["Razão e proporção","Uma maquete usa escala 1:100. Um muro de 5 cm na maquete representa quantos metros reais?",["0,5 m","5 m","50 m","500 m"],1,"5 cm × 100 = 500 cm = 5 m."],["Razão e proporção","Em uma turma, a razão entre meninos e meninas é 3:5. Se há 15 meninas, quantos meninos há?",["6","9","12","18"],1,"5 partes = 15, então cada parte = 3. Meninos: 3 × 3 = 9."],["Razão e proporção","Uma receita usa 4 ovos para 12 porções. Quantos ovos são necessários para 18 porções?",["5","6","7","8"],1,"12 porções → 4 ovos. 18 é 1,5 vez 12; 4 × 1,5 = 6."],["Razão e proporção","Num mapa, 2 cm representam 30 km. Quantos quilômetros representam 7 cm?",["90 km","100 km","105 km","120 km"],2,"1 cm representa 15 km. 7 × 15 = 105 km."],["Razão e proporção","A razão entre livros de ficção e não ficção é 4:1. Se há 25 livros no total, quantos são de ficção?",["5","10","15","20"],3,"São 5 partes no total. 25 ÷ 5 = 5 por parte; ficção: 4 × 5 = 20."]]);
port.push(...[["Ideia principal","“A escola instalou coletores para separar papel, plástico e metal. A iniciativa busca reduzir o lixo enviado ao aterro.” Qual é a ideia principal?",["A escola comprou lixeiras novas","A separação de resíduos ajuda a reduzir o lixo","O aterro fica perto da escola","Papel é o resíduo mais comum"],1,"O texto destaca a separação de resíduos como forma de reduzir o lixo enviado ao aterro."],["Ideia principal","“Ler alguns minutos por dia amplia o vocabulário e melhora a compreensão de textos. Por isso, a leitura frequente é uma prática importante.” Qual é a ideia central?",["Livros são caros","Ler diariamente traz benefícios à aprendizagem","Textos longos são sempre melhores","Vocabulário não depende de leitura"],1,"O trecho apresenta benefícios da leitura frequente."],["Ideia principal","“A ciclovia nova conecta dois bairros e permite que moradores façam parte do trajeto sem usar carro.” A ideia principal é:",["A ciclovia facilita deslocamentos de bicicleta","Os bairros são distantes","Carros foram proibidos","Todos os moradores usam bicicleta"],0,"O foco é a nova possibilidade de deslocamento entre os bairros usando bicicleta."],["Ideia principal","“O projeto de horta escolar envolve alunos no plantio e no cuidado com os alimentos. Além de produzir verduras, a atividade ensina responsabilidade.” A ideia principal é:",["A horta só serve para produzir verduras","O projeto une cultivo e aprendizagem","Alunos não gostam de plantar","Responsabilidade não se aprende na escola"],1,"O texto enfatiza tanto a produção quanto o aprendizado proporcionado pela horta."],["Ideia principal","“O uso excessivo de telas antes de dormir pode dificultar o sono. Reduzir esse uso à noite ajuda o corpo a relaxar.” O texto defende principalmente que:",["Telas devem ser proibidas","Dormir cedo é impossível","Reduzir telas à noite pode favorecer o sono","Celulares não emitem luz"],2,"A relação central é entre diminuir o uso de telas à noite e melhorar o sono."],["Ideia principal","“A biblioteca passou a emprestar jogos educativos junto com livros. A mudança procura atrair mais estudantes para o espaço.” Qual é a ideia principal?",["Jogos substituíram os livros","A biblioteca ampliou recursos para atrair estudantes","Os estudantes não leem mais","A escola vende jogos"],1,"A novidade é a ampliação dos recursos da biblioteca para aumentar a participação."],["Ideia principal","“As árvores nas cidades ajudam a diminuir o calor, oferecem sombra e melhoram a qualidade do ar.” Qual é a ideia central?",["Árvores ocupam muito espaço","Cidades não precisam de sombra","A arborização traz benefícios ao ambiente urbano","O calor só existe sem árvores"],2,"O trecho reúne benefícios da arborização urbana."],["Informação explícita","“A oficina de robótica acontecerá na quinta-feira, às 16h, no laboratório 2.” Em que local será a oficina?",["Biblioteca","Laboratório 2","Ginásio","Sala 16"],1,"O local está explicitamente informado: laboratório 2."],["Informação explícita","“As inscrições terminam em 12 de outubro e devem ser feitas pelo site da escola.” Quando terminam as inscrições?",["10 de outubro","11 de outubro","12 de outubro","15 de outubro"],2,"A data aparece diretamente no texto: 12 de outubro."],["Informação explícita","“O ônibus escolar sairá às 7h15 do portão principal.” De onde sairá o ônibus?",["Do ginásio","Do estacionamento","Do portão principal","Da biblioteca"],2,"O texto informa diretamente o ponto de saída."],["Informação explícita","“A exposição ficará aberta de terça a domingo, das 9h às 18h.” Em qual dia ela NÃO abre?",["Terça-feira","Quinta-feira","Domingo","Segunda-feira"],3,"O período informado vai de terça a domingo; segunda não está incluída."],["Informação explícita","“Para participar do torneio, cada equipe deve ter cinco jogadores e um reserva.” Quantos jogadores titulares há em cada equipe?",["4","5","6","7"],1,"O texto diz explicitamente que são cinco jogadores, além do reserva."],["Informação explícita","“O livro deve ser devolvido até 30 de setembro.” Qual é o prazo de devolução?",["20 de setembro","25 de setembro","30 de setembro","1º de outubro"],2,"A data está escrita diretamente no enunciado."],["Informação explícita","“A palestra será transmitida ao vivo pelo canal oficial da escola.” Como a palestra será transmitida?",["Pelo rádio","Pelo canal oficial da escola","Apenas presencialmente","Por mensagem"],1,"O meio de transmissão é informado diretamente."],["Informação implícita","“João entrou na sala sacudindo o casaco molhado e fechou a janela.” Pode-se inferir que:",["Estava chovendo ou havia umidade","A sala estava em festa","Era verão necessariamente","João tinha acabado de nadar"],0,"O casaco molhado e a janela fechada sugerem chuva ou tempo úmido."],["Informação implícita","“Carla conferiu o relógio várias vezes e começou a caminhar mais rápido.” O trecho sugere que ela:",["Estava com sono","Provavelmente estava atrasada ou com pressa","Queria fazer exercício","Tinha perdido o relógio"],1,"Olhar o relógio repetidamente e acelerar o passo indicam pressa."],["Informação implícita","“Ao abrir a geladeira, Marcos fez uma careta e pegou o celular para pedir comida.” É provável que:",["A geladeira estivesse cheia","Não houvesse algo que ele quisesse comer","Ele estivesse fazendo uma ligação de trabalho","A comida estivesse pronta"],1,"A reação e o pedido de comida sugerem falta de opção adequada na geladeira."],["Informação implícita","“A rua ficou silenciosa e as lojas baixaram as portas.” Pode-se concluir que:",["O comércio provavelmente estava encerrando","Começou uma corrida","Era meio-dia obrigatoriamente","As lojas estavam inaugurando"],0,"Portas baixadas e silêncio indicam encerramento das atividades."],["Informação implícita","“Beatriz colocou o uniforme, pegou a mochila e saiu cedo.” O mais provável é que ela:",["Fosse à escola","Fosse dormir","Fosse à praia","Fosse cozinhar"],0,"Uniforme, mochila e saída cedo apontam para a rotina escolar."],["Informação implícita","“O cachorro correu até a porta ao ouvir a chave girar.” Isso sugere que:",["Reconheceu a chegada de alguém","Estava dormindo profundamente","Não ouviu nada","Queria sair pela janela"],0,"A reação ao som da chave indica reconhecimento da chegada."],["Informação implícita","“Depois de ler a mensagem, André sorriu e levantou o polegar.” Pode-se inferir que:",["A mensagem provavelmente foi recebida de forma positiva","Ele não entendeu nada","A mensagem era obrigatoriamente uma notícia ruim","Ele perdeu o celular"],0,"Sorriso e gesto positivo sugerem aprovação ou satisfação."],["Inferência","“Lia levou protetor solar, chapéu e uma garrafa de água.” Qual conclusão é mais razoável?",["Ela se preparou para ficar exposta ao sol","Ela vai a uma festa noturna","Ela está indo dormir","Ela esqueceu os objetos em casa"],0,"Os itens são típicos de preparação para exposição ao sol."],["Inferência","“O professor apagou o quadro e os alunos guardaram os cadernos.” Pode-se inferir que:",["A aula provavelmente estava terminando","A aula estava começando","Havia uma prova surpresa","A escola estava vazia"],0,"Apagar o quadro e guardar materiais costuma indicar encerramento da aula."],["Inferência","“Rafaela abriu o guarda-chuva antes de sair do prédio.” O que se pode concluir?",["Provavelmente estava chovendo","Estava muito frio necessariamente","Era madrugada","Ela ia nadar"],0,"Abrir o guarda-chuva antes de sair sugere chuva."],["Inferência","“O restaurante colocou cadeiras sobre as mesas e apagou as luzes.” É provável que:",["Estivesse encerrando o expediente","Estivesse abrindo","Recebesse mais clientes","Começasse o almoço"],0,"Cadeiras sobre as mesas e luzes apagadas são sinais de fechamento."],["Inferência","“Miguel revisou o texto três vezes antes de clicar em ‘enviar’.” Isso sugere que ele:",["Queria verificar o conteúdo antes do envio","Não sabia ler","Já tinha enviado o texto","Queria apagar o computador"],0,"Revisar antes do envio mostra preocupação com a correção do conteúdo."],["Inferência","“A fila avançava lentamente e algumas pessoas olhavam o relógio.” Pode-se inferir que:",["A espera estava demorando","Não havia ninguém esperando","O atendimento era instantâneo","Todos estavam dormindo"],0,"Fila lenta e pessoas verificando o horário indicam demora."],["Inferência","“O céu ficou escuro, o vento aumentou e os vendedores recolheram as barracas.” A melhor inferência é:",["Uma tempestade podia se aproximar","O dia estava ficando mais quente","Era início da manhã necessariamente","A feira estava começando"],0,"Mudança no céu e vento forte justificam recolher barracas por previsão de mau tempo."],["Finalidade comunicativa","“Mantenha a porta fechada para conservar o ar-condicionado.” A finalidade é:",["Narrar uma história","Dar uma orientação","Fazer uma piada","Relatar uma viagem"],1,"O imperativo orienta um comportamento."],["Finalidade comunicativa","“Doe livros que você não usa. Eles podem ganhar novos leitores.” O texto pretende:",["Incentivar uma doação","Vender livros","Contar uma aventura","Descrever uma biblioteca"],0,"A mensagem busca convencer o leitor a doar livros."]]);
